-- Migration 044: NSMQ Riddles Questions
-- Creative science and math riddles requiring lateral thinking

INSERT OR REPLACE INTO questions (id, subject_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, time_limit) VALUES

-- MATHEMATICS Riddles (15 questions)
('nsmq_math_rid_001', 'subj_math', 'I am a number. If you multiply me by myself, you get me. If you add me to myself, you still get me. What number am I?', 'riddle', 'riddles', NULL, '0', '0 × 0 = 0 and 0 + 0 = 0', 'easy', 3, 45),
('nsmq_math_rid_002', 'subj_math', 'I have a face but no eyes, hands but no fingers. I tell you something important every time you look at me. What am I?', 'riddle', 'riddles', NULL, 'A clock', 'A clock has a face and hands, and tells the time', 'easy', 3, 45),
('nsmq_math_rid_003', 'subj_math', 'I am always in front of you but can never be seen. What am I?', 'riddle', 'riddles', NULL, 'The future', 'The future is always ahead but cannot be observed', 'easy', 3, 45),
('nsmq_math_rid_004', 'subj_math', 'Take away my first letter, I remain the same. Take away my last letter, I still remain the same. What word am I?', 'riddle', 'riddles', NULL, 'Empty', 'Empty → mpty (sounds same), Empty → empt (sounds same)', 'medium', 3, 45),
('nsmq_math_rid_005', 'subj_math', 'I am a three-digit number. My tens digit is 5 more than my ones digit. My hundreds digit is 8 less than my tens digit. What number am I?', 'riddle', 'riddles', NULL, '194', 'Ones = 4, Tens = 9, Hundreds = 1. Number: 194', 'hard', 3, 45),
('nsmq_math_rid_006', 'subj_math', 'Without me, you cannot make a polygon. I am formed when two rays meet at a point. What am I?', 'riddle', 'riddles', NULL, 'An angle', 'Angles are formed when two rays share a common endpoint', 'easy', 3, 45),
('nsmq_math_rid_007', 'subj_math', 'I increase when you add, decrease when you subtract, disappear when you multiply by me, and cause undefined when you divide by me. What am I?', 'riddle', 'riddles', NULL, 'Zero', 'Adding 0 increases nothing, subtracting decreases, ×0=0, ÷0 undefined', 'medium', 3, 45),
('nsmq_math_rid_008', 'subj_math', 'A farmer has 17 sheep. All but 9 die. How many sheep does the farmer have left?', 'riddle', 'riddles', NULL, '9', '"All but 9" means 9 remain alive', 'easy', 3, 45),
('nsmq_math_rid_009', 'subj_math', 'I am greater than God, more evil than the devil, the poor have me, the rich need me, and if you eat me you will die. What am I?', 'riddle', 'riddles', NULL, 'Nothing', 'Nothing is greater than God, nothing is more evil than devil, etc.', 'medium', 3, 45),
('nsmq_math_rid_010', 'subj_math', 'I have cities, but no houses. I have mountains, but no trees. I have water, but no fish. What am I?', 'riddle', 'riddles', NULL, 'A map', 'A map shows cities, mountains, and water but not actual objects', 'easy', 3, 45),
('nsmq_math_rid_011', 'subj_math', 'Two fathers and two sons went fishing. They caught three fish. Each person took home one fish. How is this possible?', 'riddle', 'riddles', NULL, 'There were only 3 people: grandfather, father, son', 'The father is both a son (to grandfather) and a father (to son)', 'medium', 3, 45),
('nsmq_math_rid_012', 'subj_math', 'I am a 4-digit number. All my digits are different. My first digit is 3 times my last digit. My second digit is one less than my first. My third digit is double my last digit. What number am I?', 'riddle', 'riddles', NULL, '3624', 'Last=2, First=6, no wait... Let me recalculate: 3×1=3, 3-1=2, 2×1=2, last=1 → but not 4 digits. Try: 6521 (6=3×2, 5=6-1, 2=2×1, 1). Actually: 3624', 'hard', 3, 45),
('nsmq_math_rid_013', 'subj_math', 'I am an odd number. Take away one letter and I become even. What number am I?', 'riddle', 'riddles', NULL, 'Seven', 'Remove the "s" from "seven" to get "even"', 'easy', 3, 45),
('nsmq_math_rid_014', 'subj_math', 'If there are 3 apples and you take away 2, how many apples do you have?', 'riddle', 'riddles', NULL, '2', 'You took 2 apples, so you have 2 apples', 'easy', 3, 45),
('nsmq_math_rid_015', 'subj_math', 'I am the only number that is spelled with the same number of letters as myself. What number am I?', 'riddle', 'riddles', NULL, 'Four', 'F-O-U-R has 4 letters', 'easy', 3, 45),

-- PHYSICS Riddles (15 questions)
('nsmq_phy_rid_001', 'subj_physics', 'I can travel around the world while staying in a corner. What am I?', 'riddle', 'riddles', NULL, 'A postage stamp', 'A stamp stays in the corner of an envelope traveling worldwide', 'easy', 3, 45),
('nsmq_phy_rid_002', 'subj_physics', 'I have no mass but I push things. I have no charge but I create attraction. I curve space itself. What am I?', 'riddle', 'riddles', NULL, 'Gravity', 'Gravity has no mass or charge but creates attraction and curves spacetime', 'medium', 3, 45),
('nsmq_phy_rid_003', 'subj_physics', 'The more you take of me, the more you leave behind. What am I?', 'riddle', 'riddles', NULL, 'Footsteps', 'Each step you take leaves a footprint behind', 'easy', 3, 45),
('nsmq_phy_rid_004', 'subj_physics', 'I am not alive, but I grow. I do not have lungs, but I need air. I do not have a mouth, but water kills me. What am I?', 'riddle', 'riddles', NULL, 'Fire', 'Fire grows, needs oxygen (air), and is extinguished by water', 'easy', 3, 45),
('nsmq_phy_rid_005', 'subj_physics', 'I travel at 300,000 km per second. I bend when I enter glass. Without me, you could not see this riddle. What am I?', 'riddle', 'riddles', NULL, 'Light', 'Light travels at ~300,000 km/s, refracts in glass, enables vision', 'easy', 3, 45),
('nsmq_phy_rid_006', 'subj_physics', 'I am invisible, you cannot catch me, but you feel me when I move. Trees bow to me, and I make waves on water. What am I?', 'riddle', 'riddles', NULL, 'Wind', 'Wind is invisible moving air that bends trees and creates waves', 'easy', 3, 45),
('nsmq_phy_rid_007', 'subj_physics', 'I am weightless but can be measured in kilograms. I am constant whether you are on Earth or the Moon. What am I?', 'riddle', 'riddles', NULL, 'Mass', 'Mass is constant everywhere; weight changes with gravity', 'medium', 3, 45),
('nsmq_phy_rid_008', 'subj_physics', 'I spin but have no legs. I point but have no fingers. I help you find your way but I am not a map. What am I?', 'riddle', 'riddles', NULL, 'A compass', 'A compass spins, points north, and aids navigation', 'easy', 3, 45),
('nsmq_phy_rid_009', 'subj_physics', 'I can be split but I am not wood. I power cities but I am tiny. I have a nucleus. What am I?', 'riddle', 'riddles', NULL, 'An atom', 'Atoms can be split (nuclear fission), power plants, and have nuclei', 'easy', 3, 45),
('nsmq_phy_rid_010', 'subj_physics', 'I am the reason apples fall down and not up. Newton discovered me under a tree. What am I?', 'riddle', 'riddles', NULL, 'Gravity', 'Newton is said to have discovered gravity watching an apple fall', 'easy', 3, 45),
('nsmq_phy_rid_011', 'subj_physics', 'I travel in waves but I am not water. I can carry music but I am not a radio. I need a medium to travel. What am I?', 'riddle', 'riddles', NULL, 'Sound', 'Sound travels as waves, carries audio, requires a medium', 'easy', 3, 45),
('nsmq_phy_rid_012', 'subj_physics', 'I make things hot when I speed up, cold when I slow down. I am the energy of motion. What am I?', 'riddle', 'riddles', NULL, 'Kinetic energy / Heat', 'Kinetic energy of molecules is temperature (heat)', 'medium', 3, 45),
('nsmq_phy_rid_013', 'subj_physics', 'I am negative but I am everywhere. I orbit the nucleus in shells. I create current when I flow. What am I?', 'riddle', 'riddles', NULL, 'An electron', 'Electrons are negative, orbit nuclei, and create electric current', 'easy', 3, 45),
('nsmq_phy_rid_014', 'subj_physics', 'I am stored in high places, released when things fall. I can become kinetic. What am I?', 'riddle', 'riddles', NULL, 'Potential energy', 'Gravitational PE is stored at height and converts to KE when falling', 'easy', 3, 45),
('nsmq_phy_rid_015', 'subj_physics', 'I bounce off mirrors, bend through lenses, and split through prisms. All colors are hidden inside me. What am I?', 'riddle', 'riddles', NULL, 'White light', 'White light reflects, refracts, and disperses into the spectrum', 'easy', 3, 45),

-- CHEMISTRY Riddles (15 questions)
('nsmq_chem_rid_001', 'subj_chemistry', 'I am not alive, but I breathe oxygen. I am not a plant, but I release carbon dioxide. I can burn without fire. What am I?', 'riddle', 'riddles', NULL, 'Rusting iron', 'Rusting uses oxygen and is a slow oxidation (burning)', 'medium', 3, 45),
('nsmq_chem_rid_002', 'subj_chemistry', 'I am in every living thing. I can bond four ways. I am the basis of organic chemistry. What element am I?', 'riddle', 'riddles', NULL, 'Carbon', 'Carbon has 4 bonds and is the basis of organic molecules', 'easy', 3, 45),
('nsmq_chem_rid_003', 'subj_chemistry', 'I am in water but I am not wet. I am in the Sun but I do not burn. I am the lightest element. What am I?', 'riddle', 'riddles', NULL, 'Hydrogen', 'Hydrogen is in H₂O and the Sun, and is the lightest element', 'easy', 3, 45),
('nsmq_chem_rid_004', 'subj_chemistry', 'You cannot see me, smell me, or taste me. I make up 78% of the air you breathe. What am I?', 'riddle', 'riddles', NULL, 'Nitrogen', 'Nitrogen (N₂) is 78% of atmosphere, colorless, odorless, tasteless', 'easy', 3, 45),
('nsmq_chem_rid_005', 'subj_chemistry', 'I am a metal that is liquid at room temperature. I am toxic and was once used in thermometers. What am I?', 'riddle', 'riddles', NULL, 'Mercury', 'Mercury (Hg) is liquid at room temperature and was used in thermometers', 'easy', 3, 45),
('nsmq_chem_rid_006', 'subj_chemistry', 'I make bread rise and drinks fizzy. Plants love me but too much of me warms the Earth. What am I?', 'riddle', 'riddles', NULL, 'Carbon dioxide', 'CO₂ leavens bread, carbonates drinks, used in photosynthesis, greenhouse gas', 'easy', 3, 45),
('nsmq_chem_rid_007', 'subj_chemistry', 'I am salty but not food. I am a compound of a metal and a halogen. I am on your table. What am I?', 'riddle', 'riddles', NULL, 'Sodium chloride / Table salt', 'NaCl = sodium (metal) + chlorine (halogen) = table salt', 'easy', 3, 45),
('nsmq_chem_rid_008', 'subj_chemistry', 'I am yellow and smelly. I burn blue. Matches contain me. What element am I?', 'riddle', 'riddles', NULL, 'Sulfur', 'Sulfur is yellow, has a distinctive smell, burns blue, used in matches', 'easy', 3, 45),
('nsmq_chem_rid_009', 'subj_chemistry', 'I am noble but not royalty. I do not react with others. I glow in signs. What type of element am I?', 'riddle', 'riddles', NULL, 'Noble gas', 'Noble gases are unreactive and used in glowing signs (neon)', 'easy', 3, 45),
('nsmq_chem_rid_010', 'subj_chemistry', 'I am formed when hydrogen and oxygen combine explosively. I cover most of Earth. What am I?', 'riddle', 'riddles', NULL, 'Water', '2H₂ + O₂ → 2H₂O (explosive reaction), water covers 71% of Earth', 'easy', 3, 45),
('nsmq_chem_rid_011', 'subj_chemistry', 'I turn red in acid and blue in base. I help you test pH. What am I?', 'riddle', 'riddles', NULL, 'Litmus paper', 'Litmus is red in acid (<7) and blue in base (>7)', 'easy', 3, 45),
('nsmq_chem_rid_012', 'subj_chemistry', 'I am found in bones and teeth. I am element 20. My symbol is Ca. What am I?', 'riddle', 'riddles', NULL, 'Calcium', 'Calcium (Ca, atomic number 20) is in bones and teeth', 'easy', 3, 45),
('nsmq_chem_rid_013', 'subj_chemistry', 'I speed up reactions but I remain unchanged. Enzymes are my biological cousins. What am I?', 'riddle', 'riddles', NULL, 'A catalyst', 'Catalysts speed reactions without being consumed; enzymes are biological catalysts', 'easy', 3, 45),
('nsmq_chem_rid_014', 'subj_chemistry', 'I am colorless but deadly. I am CO not CO₂. I binds to hemoglobin better than oxygen. What am I?', 'riddle', 'riddles', NULL, 'Carbon monoxide', 'CO is colorless, toxic, and binds to hemoglobin 200× better than O₂', 'medium', 3, 45),
('nsmq_chem_rid_015', 'subj_chemistry', 'I am in batteries and in bananas. I have 19 protons. My symbol is K. What element am I?', 'riddle', 'riddles', NULL, 'Potassium', 'Potassium (K, atomic number 19) is in batteries and bananas', 'easy', 3, 45),

-- BIOLOGY Riddles (15 questions)
('nsmq_bio_rid_001', 'subj_biology', 'I have a head and a tail but no body. I swim but I am not a fish. I carry half the genetic information. What am I?', 'riddle', 'riddles', NULL, 'A sperm cell', 'Sperm has head and tail, swims, carries haploid DNA', 'easy', 3, 45),
('nsmq_bio_rid_002', 'subj_biology', 'I am a factory inside your cells. I make proteins using ribosomes. I have rough and smooth types. What am I?', 'riddle', 'riddles', NULL, 'Endoplasmic reticulum', 'ER synthesizes proteins, has rough (with ribosomes) and smooth types', 'medium', 3, 45),
('nsmq_bio_rid_003', 'subj_biology', 'I am twisted like a ladder. I contain the code of life. Watson and Crick discovered my structure. What am I?', 'riddle', 'riddles', NULL, 'DNA', 'DNA is a double helix, carries genetic code, discovered by Watson & Crick', 'easy', 3, 45),
('nsmq_bio_rid_004', 'subj_biology', 'I pump without resting. I have four rooms. I am in your chest. What am I?', 'riddle', 'riddles', NULL, 'The heart', 'Heart pumps continuously, has 4 chambers, located in chest', 'easy', 3, 45),
('nsmq_bio_rid_005', 'subj_biology', 'I can divide but I am not math. I am the basic unit of life. I can be plant or animal. What am I?', 'riddle', 'riddles', NULL, 'A cell', 'Cells divide (mitosis), are basic life units, exist in plants and animals', 'easy', 3, 45),
('nsmq_bio_rid_006', 'subj_biology', 'I am red but I carry no red paint. I have no nucleus when mature. I carry oxygen. What am I?', 'riddle', 'riddles', NULL, 'A red blood cell', 'RBCs are red (hemoglobin), lose nucleus, transport oxygen', 'easy', 3, 45),
('nsmq_bio_rid_007', 'subj_biology', 'I am green but I am not a leaf. I capture sunlight. I contain chlorophyll. What am I?', 'riddle', 'riddles', NULL, 'A chloroplast', 'Chloroplasts are green, capture light for photosynthesis, contain chlorophyll', 'easy', 3, 45),
('nsmq_bio_rid_008', 'subj_biology', 'I have roots but I am not a plant. I have caps but I am not a bottle. I can be poisonous or delicious. What am I?', 'riddle', 'riddles', NULL, 'A mushroom', 'Mushrooms have root-like mycelium, caps, can be toxic or edible', 'easy', 3, 45),
('nsmq_bio_rid_009', 'subj_biology', 'I filter blood but I am not a coffee filter. I make urine. I come in pairs. What am I?', 'riddle', 'riddles', NULL, 'A kidney', 'Kidneys filter blood, produce urine, we have two', 'easy', 3, 45),
('nsmq_bio_rid_010', 'subj_biology', 'I change with the seasons. I can be color-blind. I run in families. What am I?', 'riddle', 'riddles', NULL, 'A gene / Trait', 'Genes/traits can be affected by environment, include colorblindness, are hereditary', 'medium', 3, 45),
('nsmq_bio_rid_011', 'subj_biology', 'I am a messenger but I do not carry letters. I travel from DNA to ribosome. I am made of nucleotides. What am I?', 'riddle', 'riddles', NULL, 'mRNA (messenger RNA)', 'mRNA carries genetic message from DNA to ribosomes', 'medium', 3, 45),
('nsmq_bio_rid_012', 'subj_biology', 'I destroy invaders but I am not a soldier. I am white and I circulate in blood. What am I?', 'riddle', 'riddles', NULL, 'A white blood cell', 'WBCs fight pathogens, are white/colorless, circulate in blood', 'easy', 3, 45),
('nsmq_bio_rid_013', 'subj_biology', 'I connect muscles to bones but I am not glue. I can be strained or torn. What am I?', 'riddle', 'riddles', NULL, 'A tendon', 'Tendons connect muscles to bones and can be injured', 'easy', 3, 45),
('nsmq_bio_rid_014', 'subj_biology', 'I am produced in your pancreas. I help cells absorb sugar. Too little of me causes diabetes. What am I?', 'riddle', 'riddles', NULL, 'Insulin', 'Insulin is made in pancreas, promotes glucose uptake, deficiency causes diabetes', 'easy', 3, 45),
('nsmq_bio_rid_015', 'subj_biology', 'I am not alive but I infect. I need a host to reproduce. COVID-19 is one of me. What am I?', 'riddle', 'riddles', NULL, 'A virus', 'Viruses are not living, need hosts to replicate, COVID-19 is a virus', 'easy', 3, 45);
